package com.zeptopluse.repository; import com.zeptopluse.entity.CustomerAddress; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface CustomerAddressRepository extends JpaRepository<CustomerAddress,Long> { List<CustomerAddress> findByCustomerIdOrderByDefaultAddressDescIdDesc(Long customerId); Optional<CustomerAddress> findByIdAndCustomerId(Long id,Long customerId); }